# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed


def _check_owner(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark for {mark.student_id} given with {student.student_id}")


def _compose(student: Student, missed: list) -> str:
    count = len(missed)
    noun = "day" if count == 1 else "days"
    dates = ", ".join(when.isoformat() for when in missed)
    return f"{student.first_name} {student.last_name} missed {count} {noun}: {dates}."


# ---
def absence_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Short notice naming the student, days missed and the dates in order."""
    marks = list(marks)
    _check_owner(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError(f"no absences for {student.student_id}")
    return _compose(student, missed)
